// Rooms per orchestrator (issue #77, FLOORS-DESIGN.md): the adapter's mapTree over the provider's tree
// (fixtures/sample-tree.json is generated by tests/test_office_tree.py from the real provider code) and the Claw3D
// patch's room/desk allocator (claw3d/cortadosRooms.ts, run here under Node's TypeScript type stripping).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile, writeFile, mkdtemp, rm } from 'node:fs/promises';
import * as nodeModule from 'node:module';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { mapTree, orchestratorFamily, OfficeGateway, RETURN_KEEP_S, RETURN_LABEL, RETURN_SEPARATOR } from './adapter.mjs';

const HERE = new URL('.', import.meta.url);
const SAMPLE = JSON.parse(await readFile(new URL('fixtures/sample-tree.json', HERE), 'utf8'));
const MINE = 'aaaaaaaaaaaaaaa1';
const OTHER = 'bbbbbbbbbbbbbbb2';
const ROOT = 't20261111090000-a0000001';
const NESTED = 't20261111090500-a0000002';
const NESTED2 = 't20261111090600-a0000003';
const NOW = SAMPLE.generated_at;
const sample = () => structuredClone(SAMPLE);
const ids = agents => agents.map(a => a.id);

// ---- the TypeScript module the Claw3D patch adds, loaded for these tests ----
const TS_SOURCE = await readFile(new URL('claw3d/cortadosRooms.ts', HERE), 'utf8');
const strip = nodeModule.stripTypeScriptTypes;   // Node >= 22.13 / 23.2; older Node skips the allocator tests
let rooms = null;
if (typeof strip === 'function') {
  const dir = await mkdtemp(join(tmpdir(), 'cortados-rooms-'));
  const file = join(dir, 'cortadosRooms.mjs');
  await writeFile(file, strip(TS_SOURCE));
  rooms = await import(pathToFileURL(file));
  await rm(dir, { recursive: true, force: true });
}
const needsTs = { skip: rooms ? false : 'Node without module.stripTypeScriptTypes (needs >= 22.13): allocator untested here' };

// ---- mapTree: grouping, ids, order ----
test('one room per orchestrator, the unattributed room last, ids carry the room', () => {
  const agents = mapTree(sample());
  const groups = [...new Set(agents.map(a => a.office.group))];
  assert.deepEqual(groups, [MINE, OTHER, 'grokbot', 'unattributed']);
  assert.deepEqual([...new Set(agents.map(a => a.office.room))], [0, 1, 2, 3]);
  for (const a of agents) {
    assert.ok(a.id.startsWith('office-' + a.office.group + '-'), a.id);
    assert.match(a.id, /^office-([0-9a-f]{16,64}|[a-z]{2,15})-(orchestrator|task-|sub-|routed-)/);
  }
  assert.ok(!agents.some(a => a.id === 'office-unattributed-orchestrator'));   // nobody orchestrates it
});

test('depth-first order: orchestrator, task, its live helpers, its nested tasks, then routed helpers', () => {
  const mine = mapTree(sample()).filter(a => a.office.group === MINE);
  assert.deepEqual(ids(mine), [
    `office-${MINE}-orchestrator`,
    `office-${MINE}-task-${ROOT}`,
    `office-${MINE}-sub-${ROOT}-c-00000000000b`,          // the running subagent; the main loop is the task itself
    `office-${MINE}-task-${NESTED}`,                       // nested after its parent's helpers
    `office-${MINE}-task-${NESTED2}`,                      // finished 100 s ago: reporting back
    `office-${MINE}-task-t20261111093000-a0000009`,        // elsewhere: state unknown, still at its desk
    `office-${MINE}-routed-mine-sub-00001`,
  ]);
  const by = Object.fromEntries(mine.map(a => [a.id, a.office]));
  assert.equal(by[`office-${MINE}-task-${NESTED}`].parent, `office-${MINE}-task-${ROOT}`);
  assert.equal(by[`office-${MINE}-task-${NESTED}`].depth, 2);
  assert.equal(by[`office-${MINE}-sub-${ROOT}-c-00000000000b`].parent, `office-${MINE}-task-${ROOT}`);
  for (const a of mine.slice(1)) {
    const parentAt = ids(mine).indexOf(a.office.parent);
    assert.ok(parentAt >= 0 && parentAt < ids(mine).indexOf(a.id), a.id + ' comes after its parent');
  }
});

test('ids are stable across polls and status changes', () => {
  const first = ids(mapTree(sample()));
  const next = sample();
  const mine = next.orchestrators.items.find(g => g.origin === MINE);
  mine.status = 'idle';
  mine.tasks[0].status = 'waiting';
  next.generated_at += 5;
  assert.deepEqual(ids(mapTree(next)), first);
  assert.equal(JSON.stringify(mapTree(sample())), JSON.stringify(mapTree(sample())));   // pure
});

test('the nameplate is title over model; metadata only', () => {
  const agents = mapTree(sample());
  const root = agents.find(a => a.id === `office-${MINE}-task-${ROOT}`);
  assert.equal(root.name, 'Build the tree');
  assert.equal(root.role, 'claude-sonnet-5');
  const orch = agents.find(a => a.id === `office-${OTHER}-orchestrator`);
  assert.equal(orch.name, 'Grounds');
  assert.equal(orch.role, 'claude-opus-5');
  const raw = JSON.stringify(agents);
  for (const banned of ['tokens', 'cache_read', '/Users/', 'SECRET', 'secret-project', 'workspace']) {
    assert.ok(!raw.includes(banned), banned);
  }
});

// ---- E8: finished work ----
const withTask = (over, group = MINE) => {
  const t = sample();
  const g = t.orchestrators.items.find(x => x.origin === group || (group === null && x.kind === 'unattributed'));
  g.tasks = [{ ...structuredClone(g.tasks[0] ?? SAMPLE.orchestrators.items[0].tasks[0]), tasks: [], sub_sessions: [],
    task_id: 't20261124120000-f0000001', title: 'Finished thing', model: 'gpt-6.1', ...over }];
  g.routed = [];
  return t;
};
const finishedId = group => `office-${group}-task-t20261124120000-f0000001`;

test('a finished task reports back beside its orchestrator for RETURN_KEEP_S, then leaves', () => {
  assert.equal(RETURN_KEEP_S, 600);
  for (const [state, status, label] of [['succeeded', 'done', 'done'], ['failed', 'failed', 'failed'],
    ['cancelled', 'done', 'cancelled']]) {
    for (const age of [0, 300, RETURN_KEEP_S]) {
      const a = mapTree(withTask({ state, status, ended_at: NOW - age, sub_sessions: [
        { ref: 'c-0000000000aa', role: 'subagent', status: 'running', model: 'x' }] }))
        .filter(x => x.office.group === MINE);
      const t = a.find(x => x.id === finishedId(MINE));
      assert.ok(t, `${state} ${age}s after its end`);
      assert.equal(t.role, label + RETURN_SEPARATOR + 'gpt-6.1');
      assert.equal(t.office.status, state === 'succeeded' ? 'idle' : 'error');   // failed and cancelled show the error
      assert.equal(t.office.returning, true);
      assert.equal(t.office.parent, `office-${MINE}-orchestrator`);
      assert.equal(t.office.returnUntil, NOW - age + RETURN_KEEP_S);
      assert.ok(!a.some(x => x.office.kind === 'helper' && x.office.parent === t.id), 'its helpers left');
    }
    const gone = mapTree(withTask({ state, status, ended_at: NOW - RETURN_KEEP_S - 1 }));
    assert.ok(!gone.some(x => x.id === finishedId(MINE)), `${state} expired`);
  }
});

test('the gateway shows a reporting failed task as an error, once', () => {
  const frames = [];
  const gateway = new OfficeGateway(f => frames.push(f));
  gateway.request({ type: 'req', id: 'c', method: 'connect' });
  const failed = withTask({ state: 'failed', status: 'failed', ended_at: NOW - 30 });
  gateway.update(failed);
  gateway.update(failed);
  const phases = frames.filter(f => f.event === 'agent' && f.payload.agentId === finishedId(MINE))
    .map(f => f.payload.data.phase);
  assert.deepEqual(phases, ['start', 'error']);   // never seen running here: opened and failed at once, not repeated
});

test('the unattributed room: no orchestrator to report to, shown only while someone is active', () => {
  const t = withTask({ state: 'succeeded', status: 'done', ended_at: NOW - 10 }, null);
  assert.ok(!mapTree(t).some(a => a.office.group === 'unattributed'));
  const active = withTask({ state: 'running', status: 'running', ended_at: null }, null);
  const people = mapTree(active).filter(a => a.office.group === 'unattributed');
  assert.deepEqual(people.map(a => a.office.kind), ['task']);
  assert.equal(mapTree(active).at(-1).office.group, 'unattributed');
});

test('a session room shows while its orchestrator is live or anyone is in it', () => {
  const quiet = withTask({ state: 'succeeded', status: 'done', ended_at: NOW - 4000 });
  quiet.orchestrators.items.find(g => g.origin === MINE).status = 'not live';
  assert.ok(!mapTree(quiet).some(a => a.office.group === MINE));
  const reporting = withTask({ state: 'succeeded', status: 'done', ended_at: NOW - 10 });
  reporting.orchestrators.items.find(g => g.origin === MINE).status = 'not live';
  assert.deepEqual(mapTree(reporting).filter(a => a.office.group === MINE).map(a => a.office.kind),
    ['orchestrator', 'task']);
});

test('helpers: each live sub-session is a person with its task; finished ones and the main loop are not', () => {
  const t = withTask({ state: 'running', status: 'running', ended_at: null, sub_sessions: [
    { ref: 'c-00000000000m', role: 'main', status: 'running', model: 'claude-sonnet-5' },
    { ref: 'c-00000000000r', role: 'subagent', status: 'running', provider: 'codex', lane: 'codex', model: 'gpt-6.1' },
    { ref: 'c-00000000000w', role: 'subagent', status: 'waiting', provider: 'local', lane: 'local-pro',
      local_backend: 'ollama', model: 'qwen3:27b' },
    { ref: 'c-00000000000d', role: 'subagent', status: 'done', model: 'x' },
    { ref: 'c-00000000000f', role: 'subagent', status: 'failed', model: 'y' }] });
  const helpers = mapTree(t).filter(a => a.office.kind === 'helper' && a.office.group === MINE);
  assert.deepEqual(helpers.map(a => [a.id.split('-sub-')[1], a.office.status, a.office.characterFamily]), [
    ['t20261124120000-f0000001-c-00000000000r', 'working', 'codex'],
    ['t20261124120000-f0000001-c-00000000000w', 'idle', 'ollama']]);
  assert.ok(helpers.every(a => a.office.parent === finishedId(MINE)));
});

// ---- E7: the orchestrator's suit ----
test('family sources in order: bot, the provider\'s client (wire, heartbeat), else a marked model guess', () => {
  const g = Object.fromEntries(mapTree(sample()).filter(a => a.office.kind === 'orchestrator')
    .map(a => [a.office.group, a.office]));
  assert.deepEqual([g.grokbot.characterFamily, g.grokbot.familySource], ['grok', 'bot']);
  assert.deepEqual([g[OTHER].characterFamily, g[OTHER].familySource], ['codex', 'wire']);   // a Claude model in Codex
  assert.deepEqual([g[MINE].characterFamily, g[MINE].familySource], ['claude', 'model-guess']);
  for (const o of Object.values(g)) assert.equal(o.provider, null);    // never published as a provider
  const cases = [
    [{ kind: 'bot', client: 'codex', client_source: 'wire', model: 'gpt-6.1' }, 'grok', 'bot'],
    [{ kind: 'session', client: 'claude-code', client_source: 'wire', model: 'gpt-6.1' }, 'claude', 'wire'],
    [{ kind: 'session', client: 'codex', client_source: 'heartbeat', model: 'claude-opus-5' }, 'codex', 'heartbeat'],
    [{ kind: 'session', client: 'grok', client_source: 'heartbeat', model: null }, 'grok', 'heartbeat'],
    [{ kind: 'session', client: 'antigravity', client_source: 'heartbeat', model: 'gemini-3' }, 'unknown', 'heartbeat'],
    [{ kind: 'session', client: 'codex', client_source: 'made-up', model: 'claude-opus-5' }, 'claude', 'model-guess'],
    [{ kind: 'session', client: '__proto__', client_source: 'wire', model: 'gpt-6.1' }, 'codex', 'model-guess'],
    [{ kind: 'session', client: null, client_source: null, model: 'gemini-3' }, 'unknown', 'model-guess'],
  ];
  for (const [group, family, source] of cases) {
    assert.deepEqual(orchestratorFamily(group), { family, source }, JSON.stringify(group));
  }
  const suit = mapTree(sample()).find(a => a.id === `office-${OTHER}-orchestrator`);
  assert.equal(suit.office.sprite, 'codex-suit');
  assert.equal(suit.office.outfit, 'suit');
});

// ---- the Claw3D side: layout and allocation (E6: 8 rooms x 6 desks) ----
const deskItemsOf = layout => layout.filter(i => i.type === 'desk_cubicle');
const agentsOf = tree => mapTree(tree).map(a => ({ id: a.id, subtitle: a.role }));

test('the patch carries this module unchanged and recognises every adapter id and return label', needsTs, () => {
  for (const a of mapTree(sample())) assert.ok(rooms.isCortadosAgentId(a.id), a.id);
  for (const stock of ['main', 'agent-1', 'office-lobby-worker-run-1', 'remote:office-x', 'office--orchestrator']) {
    assert.equal(rooms.isCortadosAgentId(stock), false, stock);
  }
  for (const label of Object.values(RETURN_LABEL)) {
    assert.ok(rooms.CORTADOS_RETURN_SUBTITLE.test(label + RETURN_SEPARATOR + 'm'), label);
  }
  assert.equal(rooms.CORTADOS_RETURN_SUBTITLE.test('claude-sonnet-5'), false);
});

test('the patch file embeds claw3d/cortadosRooms.ts byte for byte and stays a small hook', async () => {
  const patch = await readFile(new URL('claw3d/cortados-rooms.patch', HERE), 'utf8');
  const parts = patch.split(/^diff --git /m).filter(Boolean);
  const file = parts.find(p => p.startsWith('a/src/features/retro-office/core/cortadosRooms.ts'));
  assert.ok(file && /^new file mode/m.test(file));
  const added = file.split('\n').filter(l => l.startsWith('+') && !l.startsWith('+++')).map(l => l.slice(1));
  assert.equal(added.join('\n') + '\n', TS_SOURCE);
  const hook = parts.find(p => p.startsWith('a/src/features/retro-office/RetroOffice3D.tsx'));
  const changed = hook.split('\n').filter(l => /^[+-](?![+-])/.test(l));
  assert.ok(changed.length <= 30, 'RetroOffice3D.tsx hook is ' + changed.length + ' changed lines');
  assert.equal(parts.length, 2);
});

test('layout: 8 rooms, each a head desk, 2 report desks and 6 team desks, inside the 1800 x 720 office', needsTs, () => {
  const layout = rooms.buildCortadosRoomsLayout();
  assert.ok(rooms.isCortadosLayout(layout));
  assert.equal(rooms.isCortadosLayout([{ _uid: 'office_0', type: 'desk_cubicle', x: 0, y: 0 }]), false);
  const desks = deskItemsOf(layout);
  assert.equal(desks.length, rooms.CORTADOS_ROOMS * (1 + rooms.CORTADOS_REPORT_DESKS + rooms.CORTADOS_TEAM_DESKS));
  assert.equal(rooms.CORTADOS_ROOMS, 8);
  assert.equal(rooms.CORTADOS_TEAM_DESKS, 6);
  assert.equal(new Set(layout.map(i => i._uid)).size, layout.length);
  for (const i of layout) {
    assert.ok(i.x >= 0 && i.y >= 0 && i.x + (i.w ?? 100) <= 1800 && i.y + (i.h ?? 55) <= 720, i._uid);
  }
  // no desk overlaps a wall or another desk (desk_cubicle footprint 100 x 55, geometry.ts ITEM_FOOTPRINT)
  const box = i => i.type === 'wall' ? [i.x, i.y, i.w, i.h] : [i.x, i.y, 100, 55];
  const solid = layout.filter(i => i.type === 'wall' || i.type === 'desk_cubicle');
  for (const a of desks) {
    for (const b of solid) {
      if (a === b) continue;
      const [ax, ay, aw, ah] = box(a); const [bx, by, bw, bh] = box(b);
      assert.ok(ax + aw <= bx || bx + bw <= ax || ay + ah <= by || by + bh <= ay, a._uid + ' overlaps ' + b._uid);
    }
  }
});

test('allocation: orchestrator at the head desk, team in order, reporters beside it, everyone held', needsTs, () => {
  const desks = deskItemsOf(rooms.buildCortadosRoomsLayout());
  const state = rooms.createCortadosRoomState();
  const agents = agentsOf(sample());
  const { desks: seat, holds } = rooms.allocateCortadosDesks(agents, desks, {}, state);
  const uid = id => desks[seat[id]]?._uid;
  assert.equal(uid(`office-${MINE}-orchestrator`), 'cortados_r0_head0');
  assert.equal(uid(`office-${MINE}-task-${ROOT}`), 'cortados_r0_desk0');
  assert.equal(uid(`office-${MINE}-sub-${ROOT}-c-00000000000b`), 'cortados_r0_desk1');
  assert.equal(uid(`office-${MINE}-task-${NESTED}`), 'cortados_r0_desk2');
  assert.equal(uid(`office-${MINE}-task-${NESTED2}`), 'cortados_r0_report0');   // finished: reports back
  assert.equal(uid(`office-${OTHER}-orchestrator`), 'cortados_r1_head0');
  assert.equal(uid('office-grokbot-orchestrator'), 'cortados_r2_head0');
  assert.ok(uid(`office-unattributed-task-t20261111095500-d0000002`).startsWith('cortados_r3_desk'));
  assert.deepEqual(Object.keys(holds).sort(), Object.keys(seat).sort());
  assert.ok(Object.values(holds).every(Boolean));
});

test('overflow: a 9th orchestrator and a 7th teammate stay unseated (stock behaviour); 3 reporters seat 2', needsTs, () => {
  const desks = deskItemsOf(rooms.buildCortadosRoomsLayout());
  const people = [];
  for (let g = 0; g < 9; g += 1) {
    const tag = g.toString(16).padStart(16, 'c');
    people.push({ id: `office-${tag}-orchestrator` });
    for (let t = 0; t < 7; t += 1) people.push({ id: `office-${tag}-task-t2026112410000${t}-a000000${g}` });
    for (let r = 0; r < 3; r += 1) {
      people.push({ id: `office-${tag}-task-t2026112410100${r}-b000000${g}`, subtitle: 'failed · gpt-6.1' });
    }
  }
  const { desks: seat } = rooms.allocateCortadosDesks(people, desks, {}, rooms.createCortadosRoomState());
  const seated = tag => people.filter(p => p.id.startsWith(`office-${tag}-`) && p.id in seat);
  for (let g = 0; g < 8; g += 1) {
    const tag = g.toString(16).padStart(16, 'c');
    const s = seated(tag);
    assert.equal(s.length, 1 + 6 + 2, tag);                         // head + 6 team + 2 report desks
    assert.ok(!(`office-${tag}-task-t20261124100006-a000000${g}` in seat), 'the 7th teammate stands');
    assert.ok(!(`office-${tag}-task-t20261124101002-b000000${g}` in seat), 'the 3rd reporter stands');
  }
  assert.equal(seated('8'.padStart(16, 'c')).length, 0);           // no 9th room
  assert.equal(new Set(Object.values(seat)).size, Object.keys(seat).length);   // one person per desk
});

test('sticky: rooms and seats never move while their people stay; a freed room is reused', needsTs, () => {
  const desks = deskItemsOf(rooms.buildCortadosRoomsLayout());
  const state = rooms.createCortadosRoomState();
  const a = 'a'.repeat(16); const b = 'b'.repeat(16); const c = 'c'.repeat(16);
  const p = (g, rest = 'orchestrator') => ({ id: `office-${g}-${rest}` });
  let r = rooms.allocateCortadosDesks([p(a), p(b), p(b, 'task-t20261124100000-a0000001')], desks, {}, state);
  const before = { ...r.desks };
  // c arrives first in the order, a task of b's ahead of the earlier one: nothing seated moves
  r = rooms.allocateCortadosDesks([p(c), p(b, 'task-t20261124100000-a0000002'), p(b), p(a),
    p(b, 'task-t20261124100000-a0000001')], desks, {}, state);
  for (const [id, index] of Object.entries(before)) assert.equal(r.desks[id], index, id);
  assert.equal(desks[r.desks[p(c).id]]._uid, 'cortados_r2_head0');
  // a leaves: its room is free for the next newcomer
  r = rooms.allocateCortadosDesks([p(b), p(c), p('d'.repeat(16))], desks, {}, state);
  assert.equal(desks[r.desks[p('d'.repeat(16)).id]]._uid, 'cortados_r0_head0');
  // a running task that finishes moves from its team desk to a report desk
  const t = 'task-t20261124100000-a0000001';
  r = rooms.allocateCortadosDesks([p(b), { id: `office-${b}-${t}`, subtitle: 'done · gpt-6.1' }], desks, {}, state);
  assert.equal(desks[r.desks[`office-${b}-${t}`]]._uid, 'cortados_r1_report0');
});

test('a desk or person placed by hand always wins', needsTs, () => {
  const desks = deskItemsOf(rooms.buildCortadosRoomsLayout());
  const a = 'a'.repeat(16);
  const manual = { cortados_r0_head0: 'someone-else', cortados_r0_desk0: `office-${a}-task-t20261124100000-a0000009` };
  const { desks: seat } = rooms.allocateCortadosDesks([{ id: `office-${a}-orchestrator` },
    { id: `office-${a}-task-t20261124100000-a0000009` }, { id: `office-${a}-task-t20261124100000-a0000001` }],
  desks, manual, rooms.createCortadosRoomState());
  assert.ok(!(`office-${a}-orchestrator` in seat), 'its head desk is someone\'s by hand: the orchestrator stands');
  assert.ok(!(`office-${a}-task-t20261124100000-a0000009` in seat), 'Studio seats it, not us');
  assert.equal(desks[seat[`office-${a}-task-t20261124100000-a0000001`]]._uid, 'cortados_r0_desk1');
});

test('off unless the CortadOS bridge is the connected gateway', needsTs, () => {
  const ours = agentsOf(sample());
  assert.equal(rooms.cortadosRoomsActive(ours, 'connected'), true);
  assert.equal(rooms.cortadosRoomsActive([...ours, { id: 'remote:office-x' }], 'connected'), true);
  assert.equal(rooms.cortadosRoomsActive(ours, 'connecting'), false);
  assert.equal(rooms.cortadosRoomsActive(ours, undefined), false);
  assert.equal(rooms.cortadosRoomsActive([...ours, { id: 'main' }], 'connected'), false);
  assert.equal(rooms.cortadosRoomsActive([], 'connected'), false);
});
